  <template v-if="connection">
   <div class="product-summary"><div><span>{{ tr('权威来源状态','Trạng thái nguồn') }}</span><b>{{ status(connection.state) }}</b></div><div><span>{{ tr('最近完整同步','Đồng bộ đầy đủ gần nhất') }}</span><b style="font-size:16px">{{ connection.lastCompleteAt || tr('尚无记录','Chưa có') }}</b></div><div><span>{{ tr('切换生效日','Ngày chuyển đổi') }}</span><b style="font-size:16px">{{ connection.effectiveDate || tr('未切换','Chưa chuyển') }}</b></div></div>
   <el-alert v-if="running" :title="tr('后台同步中，每五秒刷新批次进度；未完成前不会推进完整同步水位。','Đang đồng bộ nền, cập nhật mỗi 5 giây; mốc đầy đủ chỉ thay đổi khi hoàn tất.')" type="info" :closable="false"/><el-tabs v-model="tab" @tab-change="name => name === 'cutover' && loadCutover()">
    <el-tab-pane v-if="canManage" :label="tr('人员映射','Ánh xạ nhân sự')" name="mappings"><div class="product-toolbar"><el-button type="primary" :disabled="running" @click="openMapping">{{ tr('建立映射','Tạo ánh xạ') }}</el-button></div><el-alert :title="tr('按飞书考勤员工标识绑定本地人员，不按姓名自动合并。停用或改绑不修改历史记录。','Liên kết bằng mã nhân sự chấm công Feishu, không tự ghép theo tên. Dừng ánh xạ không sửa lịch sử.')" type="info" :closable="false"/><el-table :data="mappings"><el-table-column :label="tr('人员','Nhân sự')"><template #default="{row}">{{ row.userName || personName(row.userId) }}</template></el-table-column><el-table-column prop="externalUserId" :label="tr('飞书员工标识','Mã nhân sự Feishu')" min-width="150"/><el-table-column prop="effectiveFrom" :label="tr('生效日期','Ngày hiệu lực')"/><el-table-column prop="effectiveTo" :label="tr('截止日期','Ngày kết thúc')"/><el-table-column :label="tr('状态','Trạng thái')"><template #default="{row}">{{ status(row.status) }}</template></el-table-column><el-table-column :label="tr('操作','Thao tác')"><template #default="{row}"><el-button v-if="row.status === 'CONFIRMED'" link type="danger" :disabled="running" @click="retire(row)">{{ tr('停用','Dừng') }}</el-button></template></el-table-column></el-table></el-tab-pane>
    <el-tab-pane :label="tr('同步与异常','Đồng bộ và lỗi')" name="runs"><div v-if="canManage" class="product-toolbar"><el-date-picker v-model="syncDates" type="daterange" value-format="YYYY-MM-DD"/><el-button type="primary" :loading="syncing" :disabled="running || !connection.configured" @click="runSync">{{ tr('同步所选范围','Đồng bộ khoảng đã chọn') }}</el-button></div><el-table :data="runs"><el-table-column prop="runId" :label="tr('批次','Lần chạy')" width="85"/><el-table-column :label="tr('范围','Phạm vi')" min-width="185"><template #default="{row}">{{ row.windowStart }} — {{ row.windowEnd }}</template></el-table-column><el-table-column :label="tr('状态','Trạng thái')"><template #default="{row}">{{ status(row.status) }}</template></el-table-column><el-table-column :label="tr('分片进度','Tiến độ phần')" width="110"><template #default="{row}">{{ row.completedChunks || 0 }}/{{ row.expectedChunks || 0 }}</template></el-table-column><el-table-column prop="receivedCount" :label="tr('读取数','Số bản ghi')"/><el-table-column prop="rejectedCount" :label="tr('待核实','Cần kiểm tra')"/><el-table-column prop="finishedAt" :label="tr('完成时间','Thời gian kết thúc')" min-width="170"/><el-table-column :label="tr('异常说明','Mô tả lỗi')" min-width="220"><template #default="{row}">{{ issueText(row.errorCode) }}</template></el-table-column></el-table></el-tab-pane>
