     <div class="product-toolbar"><el-date-picker v-model="effectiveDate" type="date" value-format="YYYY-MM-DD" @change="loadCutover"/><el-button @click="loadCutover">{{ tr('检查切换条件','Kiểm tra điều kiện') }}</el-button><el-button v-hasPermi="['business:attendance:cutover']" @click="openValidation">{{ tr('登记真实样本验收','Ghi nhận kiểm tra mẫu thật') }}</el-button><el-button v-if="cutover?.canActivate" v-hasPermi="['business:attendance:cutover']" type="warning" :loading="saving" @click="activate">{{ tr('确认切换','Xác nhận chuyển đổi') }}</el-button></div>
     <ul v-if="cutover?.blockers?.length"><li v-for="(b,i) in cutover.blockers" :key="i">{{ blockerText(typeof b==='string'?b:b.label || b.message || b.code) }}</li></ul><el-result v-else-if="cutover?.canActivate" icon="success" :title="tr('检查通过，等待业务负责人确认','Đã đạt kiểm tra, chờ người phụ trách xác nhận')"/>
